IF NOT EXISTS(select * from sysobjects where id = object_id(N'[dbo].[ateco]') and OBJECTPROPERTY(id, N'IsUserTable') = 1)
BEGIN
CREATE TABLE [dbo].[ateco] (
idateco int NOT NULL,
codice varchar(50) NULL,
lt datetime NULL,
lu varchar(64) NULL,
title varchar(255) NULL,
 CONSTRAINT xpkateco PRIMARY KEY (idateco
)
)
END
GO

-- VERIFICA STRUTTURA ateco --
IF NOT exists(select * from [sysobjects] as T inner join syscolumns C on T.ID = C.ID where t.name = 'ateco' and C.name = 'idateco' AND (T.uid = USER_ID( ) OR T.uid = USER_ID('dbo')))
BEGIN
	ALTER TABLE [ateco] ADD idateco int NOT NULL DEFAULT 0
	declare @vincolo varchar(100)
	select @vincolo = object_name(const.constid) from syscolumns col join sysconstraints const on const.id = col.id and const.colid = col.colid where col.id = object_id('ateco') and col.name = 'idateco' and objectproperty(const.constid, 'IsDefaultCnst')=1
	exec ('ALTER TABLE [ateco] drop constraint '+@vincolo)
END
GO

