-- CREAZIONE VISTA affidamentodefaultview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[affidamentodefaultview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[affidamentodefaultview]
GO

CREATE VIEW [dbo].[affidamentodefaultview] AS SELECT  affidamento.aa, affidamento.ct AS affidamento_ct, affidamento.cu AS affidamento_cu,CASE WHEN affidamento.freqobbl = 'S' THEN 'Si' WHEN affidamento.freqobbl = 'N' THEN 'No' END AS affidamento_freqobbl, affidamento.frequenzaminima AS affidamento_frequenzaminima, affidamento.frequenzaminimadebito AS affidamento_frequenzaminimadebito,CASE WHEN affidamento.gratuito = 'S' THEN 'Si' WHEN affidamento.gratuito = 'N' THEN 'No' END AS affidamento_gratuito, affidamento.idaffidamento, [dbo].affidamentokind.title AS affidamentokind_title, affidamento.idaffidamentokind AS affidamento_idaffidamentokind, affidamento.idattivform, affidamento.idcanale, affidamento.idcorsostudio, affidamento.iddidprog, affidamento.iddidproganno, affidamento.iddidprogcurr, affidamento.iddidprogori, affidamento.iddidprogporzanno, [dbo].erogazkind.title AS erogazkind_title, affidamento.iderogazkind AS affidamento_iderogazkind, registry_registry_docentidocenti.title AS registrydocenti_title, affidamento.idreg_docenti, affidamento.idsede AS affidamento_idsede, affidamento.json, affidamento.jsonancestor AS affidamento_jsonancestor, affidamento.lt AS affidamento_lt, affidamento.lu AS affidamento_lu, affidamento.orariric AS affidamento_orariric, affidamento.orariric_en AS affidamento_orariric_en, affidamento.paridaffidamento AS affidamento_paridaffidamento, affidamento.prog AS affidamento_prog, affidamento.prog_en AS affidamento_prog_en,CASE WHEN affidamento.riferimento = 'S' THEN 'Si' WHEN affidamento.riferimento = 'N' THEN 'No' END AS affidamento_riferimento, affidamento.start AS affidamento_start, affidamento.stop AS affidamento_stop, affidamento.testi AS affidamento_testi, affidamento.testi_en AS affidamento_testi_en, affidamento.title AS affidamento_title, affidamento.urlcorso AS affidamento_urlcorso, isnull('Affidamento: ' + affidamento.json + '; ','') as dropdown_title FROM [dbo].affidamento WITH (NOLOCK)  LEFT OUTER JOIN [dbo].affidamentokind WITH (NOLOCK) ON affidamento.idaffidamentokind = [dbo].affidamentokind.idaffidamentokind LEFT OUTER JOIN [dbo].erogazkind WITH (NOLOCK) ON affidamento.iderogazkind = [dbo].erogazkind.iderogazkind LEFT OUTER JOIN [dbo].registry_docenti AS registry_docentidocenti WITH (NOLOCK) ON affidamento.idreg_docenti = registry_docentidocenti.idreg LEFT OUTER JOIN [dbo].registry AS registry_registry_docentidocenti WITH (NOLOCK) ON registry_docentidocenti.idreg = registry_registry_docentidocenti.idreg WHERE  affidamento.aa IS NOT NULL  AND affidamento.idaffidamento IS NOT NULL  AND affidamento.idattivform IS NOT NULL  AND affidamento.idcanale IS NOT NULL  AND affidamento.idcorsostudio IS NOT NULL  AND affidamento.iddidprog IS NOT NULL  AND affidamento.iddidproganno IS NOT NULL  AND affidamento.iddidprogcurr IS NOT NULL  AND affidamento.iddidprogori IS NOT NULL  AND affidamento.iddidprogporzanno IS NOT NULL 
GO

