-- FINE GENERAZIONE SCRIPT --

--[DBO]--
-- CREAZIONE VISTA didprogingressoview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[didprogingressoview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[didprogingressoview]
GO

CREATE VIEW [dbo].[didprogingressoview] AS SELECT  didprog.aa, didprog.annosolare AS didprog_annosolare, didprog.attribdebiti AS didprog_attribdebiti, didprog.ciclo AS didprog_ciclo, didprog.codice AS didprog_codice, didprog.codicemiur AS didprog_codicemiur, didprog.dataconsmaxiscr AS didprog_dataconsmaxiscr,CASE WHEN didprog.freqobbl = 'S' THEN 'Si' WHEN didprog.freqobbl = 'N' THEN 'No' END AS didprog_freqobbl, didprog.idareadidattica AS didprog_idareadidattica, didprog.idconvenzione AS didprog_idconvenzione, [dbo].corsostudio.title AS corsostudio_title, [dbo].corsostudio.annoistituz AS corsostudio_annoistituz, didprog.idcorsostudio, didprog.iddidprog, [dbo].didprognumchiusokind.title AS didprognumchiusokind_title, didprog.iddidprognumchiusokind AS didprog_iddidprognumchiusokind, didprog.iddidprogsuddannokind AS didprog_iddidprogsuddannokind, didprog.iderogazkind AS didprog_iderogazkind, [dbo].graduatoria.title AS graduatoria_title, didprog.idgraduatoria, geo_nationlang.title AS geo_nationlang_title, didprog.idnation_lang, geo_nationlang2.title AS geo_nationlang2_title, didprog.idnation_lang2, geo_nationlangvis.title AS geo_nationlangvis_title, didprog.idnation_langvis, didprog.idreg_docenti AS didprog_idreg_docenti, [dbo].sede.title AS sede_title, didprog.idsede, [dbo].sessionekind.title AS sessionekind_title, [dbo].sessione.start AS sessione_start, [dbo].sessione.stop AS sessione_stop, didprog.idsessione, [dbo].titolokind.title AS titolokind_title, didprog.idtitolokind AS didprog_idtitolokind,CASE WHEN didprog.immatoltreauth = 'S' THEN 'Si' WHEN didprog.immatoltreauth = 'N' THEN 'No' END AS didprog_immatoltreauth, didprog.modaccesso AS didprog_modaccesso, didprog.modaccesso_en AS didprog_modaccesso_en, didprog.obbformativi AS didprog_obbformativi, didprog.obbformativi_en AS didprog_obbformativi_en,CASE WHEN didprog.preimmatoltreauth = 'S' THEN 'Si' WHEN didprog.preimmatoltreauth = 'N' THEN 'No' END AS didprog_preimmatoltreauth, didprog.progesamamm AS didprog_progesamamm, didprog.prospoccupaz AS didprog_prospoccupaz, didprog.provafinaledesc AS didprog_provafinaledesc, didprog.regolamentotax AS didprog_regolamentotax, didprog.regolamentotaxurl AS didprog_regolamentotaxurl, didprog.startiscrizioni AS didprog_startiscrizioni, didprog.stopiscrizioni AS didprog_stopiscrizioni, didprog.title, didprog.title_en AS didprog_title_en, didprog.utenzasost AS didprog_utenzasost, didprog.website AS didprog_website, isnull('Denominazione: ' + didprog.title + '; ','') + ' ' + isnull('Tipologia Tipologia: ' + [dbo].sessionekind.title + '; ','') + ' ' + isnull('Anno accademico: ' + didprog.aa + '; ','') as dropdown_title FROM [dbo].didprog WITH (NOLOCK)  LEFT OUTER JOIN [dbo].corsostudio WITH (NOLOCK) ON didprog.idcorsostudio = [dbo].corsostudio.idcorsostudio LEFT OUTER JOIN [dbo].didprognumchiusokind WITH (NOLOCK) ON didprog.iddidprognumchiusokind = [dbo].didprognumchiusokind.iddidprognumchiusokind LEFT OUTER JOIN [dbo].graduatoria WITH (NOLOCK) ON didprog.idgraduatoria = [dbo].graduatoria.idgraduatoria LEFT OUTER JOIN [dbo].geo_nation AS geo_nationlang WITH (NOLOCK) ON didprog.idnation_lang = geo_nationlang.idnation LEFT OUTER JOIN [dbo].geo_nation AS geo_nationlang2 WITH (NOLOCK) ON didprog.idnation_lang2 = geo_nationlang2.idnation LEFT OUTER JOIN [dbo].geo_nation AS geo_nationlangvis WITH (NOLOCK) ON didprog.idnation_langvis = geo_nationlangvis.idnation LEFT OUTER JOIN [dbo].sede WITH (NOLOCK) ON didprog.idsede = [dbo].sede.idsede LEFT OUTER JOIN [dbo].sessione WITH (NOLOCK) ON didprog.idsessione = [dbo].sessione.idsessione LEFT OUTER JOIN [dbo].sessionekind WITH (NOLOCK) ON sessione.idsessionekind = [dbo].sessionekind.idsessionekind LEFT OUTER JOIN [dbo].titolokind WITH (NOLOCK) ON didprog.idtitolokind = [dbo].titolokind.idtitolokind WHERE  didprog.idcorsostudio IS NOT NULL  AND didprog.iddidprog IS NOT NULL 
GO

