-- CREAZIONE VISTA iscrizioneseganagstuaccview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[iscrizioneseganagstuaccview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[iscrizioneseganagstuaccview]
GO

CREATE VIEW [dbo].[iscrizioneseganagstuaccview] AS SELECT  iscrizione.aa, iscrizione.anno AS iscrizione_anno, iscrizione.ct AS iscrizione_ct, iscrizione.cu AS iscrizione_cu, iscrizione.data AS iscrizione_data, iscrizione.idcorsostudio, [dbo].didprog.title AS didprog_title, [dbo].annoaccademico.aa AS annoaccademico_aa, [dbo].sede.title AS sede_title, iscrizione.iddidprog, iscrizione.idiscrizione, iscrizione.idreg, iscrizione.lt AS iscrizione_lt, iscrizione.lu AS iscrizione_lu, iscrizione.matricola AS iscrizione_matricola, isnull('Codice Anno accademico: ' + [dbo].annoaccademico.aa + '; ','') + ' ' + isnull('Prova di accesso: ' + [dbo].didprog.title + '; ','') + ' ' + isnull('Anno accademico: ' + iscrizione.aa + '; ','') + ' ' + isnull('Denominazione Sede: ' + [dbo].sede.title + '; ','') as dropdown_title FROM [dbo].iscrizione WITH (NOLOCK)  LEFT OUTER JOIN [dbo].didprog WITH (NOLOCK) ON iscrizione.iddidprog = [dbo].didprog.iddidprog LEFT OUTER JOIN [dbo].annoaccademico WITH (NOLOCK) ON didprog.aa = [dbo].annoaccademico.aa LEFT OUTER JOIN [dbo].sede WITH (NOLOCK) ON didprog.idsede = [dbo].sede.idsede WHERE  iscrizione.idcorsostudio  in (select cs.idcorsostudio from corsostudio cs where cs.idcorsostudiokind = 12 /*test di ingresso*/) AND iscrizione.idcorsostudio IS NOT NULL  AND iscrizione.iddidprog IS NOT NULL  AND iscrizione.idiscrizione IS NOT NULL  AND iscrizione.idreg IS NOT NULL 
GO

