-- FINE GENERAZIONE SCRIPT --

--[DBO]--
-- CREAZIONE VISTA registryaziendeview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[registryaziendeview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[registryaziendeview]
GO

CREATE VIEW [dbo].[registryaziendeview] AS SELECT CASE WHEN registry.active = 'S' THEN 'Si' WHEN registry.active = 'N' THEN 'No' END AS registry_active, registry.annotation AS registry_annotation,CASE WHEN registry.authorization_free = 'S' THEN 'Si' WHEN registry.authorization_free = 'N' THEN 'No' END AS registry_authorization_free, registry.badgecode AS registry_badgecode, registry.birthdate AS registry_birthdate, registry.ccp AS registry_ccp, registry.cf AS registry_cf, registry.ct AS registry_ct, registry.cu AS registry_cu, registry.email_fe AS registry_email_fe, registry.extension AS registry_extension, registry.extmatricula AS registry_extmatricula,CASE WHEN registry.flag_pa = 'S' THEN 'Si' WHEN registry.flag_pa = 'N' THEN 'No' END AS registry_flag_pa,CASE WHEN registry.flagbankitaliaproceeds = 'S' THEN 'Si' WHEN registry.flagbankitaliaproceeds = 'N' THEN 'No' END AS registry_flagbankitaliaproceeds, registry.foreigncf AS registry_foreigncf, registry.forename AS registry_forename,CASE WHEN registry.gender = 'S' THEN 'Si' WHEN registry.gender = 'N' THEN 'No' END AS registry_gender, [dbo].category.description AS category_description, registry.idcategory, registry.idcentralizedcategory AS registry_idcentralizedcategory, [dbo].geo_city.title AS geo_city_title, registry.idcity, registry.idexternal AS registry_idexternal, registry.idmaritalstatus AS registry_idmaritalstatus, [dbo].geo_nation.title AS geo_nation_title, registry.idnation, registry.idreg, [dbo].registryclass.description AS registryclass_description, registry.idregistryclass, [dbo].registrykind.description AS registrykind_description, registry.idregistrykind AS registry_idregistrykind, registry.idtitle AS registry_idtitle, registry.ipa_fe AS registry_ipa_fe, registry.ipa_perlapa AS registry_ipa_perlapa, registry.location AS registry_location, registry.lt AS registry_lt, registry.lu AS registry_lu, registry.maritalsurname AS registry_maritalsurname,CASE WHEN registry.multi_cf = 'S' THEN 'Si' WHEN registry.multi_cf = 'N' THEN 'No' END AS registry_multi_cf, registry.p_iva AS registry_p_iva, registry.pec_fe AS registry_pec_fe, [dbo].residence.description AS residence_description, registry.residence, registry.rtf AS registry_rtf, registry.sdi_defrifamm AS registry_sdi_defrifamm,CASE WHEN registry.sdi_norifamm = 'S' THEN 'Si' WHEN registry.sdi_norifamm = 'N' THEN 'No' END AS registry_sdi_norifamm, registry.surname AS registry_surname, registry.title, registry.toredirect AS registry_toredirect, registry.txt AS registry_txt, registry_aziende.ct AS registry_aziende_ct, registry_aziende.cu AS registry_aziende_cu, [dbo].ateco.codice AS ateco_codice, [dbo].ateco.title AS ateco_title, registry_aziende.idateco, [dbo].nace.idnace AS nace_idnace, [dbo].nace.activity AS nace_activity, registry_aziende.idnace, [dbo].naturagiur.title AS naturagiur_title, registry_aziende.idnaturagiur, [dbo].numerodip.title AS numerodip_title, registry_aziende.idnumerodip, registry_aziende.idreg AS registry_aziende_idreg, registry_aziende.lt AS registry_aziende_lt, registry_aziende.lu AS registry_aziende_lu, registry_aziende.pic AS registry_aziende_pic, registry_aziende.title_en AS registry_aziende_title_en, registry_aziende.txt_en AS registry_aziende_txt_en, isnull('Denominazione: ' + registry.title + '; ','') as dropdown_title FROM [dbo].registry WITH (NOLOCK)  INNER JOIN registry_aziende WITH (NOLOCK) ON registry.idreg = registry_aziende.idreg LEFT OUTER JOIN [dbo].category WITH (NOLOCK) ON registry.idcategory = [dbo].category.idcategory LEFT OUTER JOIN [dbo].geo_city WITH (NOLOCK) ON registry.idcity = [dbo].geo_city.idcity LEFT OUTER JOIN [dbo].geo_nation WITH (NOLOCK) ON registry.idnation = [dbo].geo_nation.idnation LEFT OUTER JOIN [dbo].registryclass WITH (NOLOCK) ON registry.idregistryclass = [dbo].registryclass.idregistryclass LEFT OUTER JOIN [dbo].registrykind WITH (NOLOCK) ON registry.idregistrykind = [dbo].registrykind.idregistrykind LEFT OUTER JOIN [dbo].residence WITH (NOLOCK) ON registry.residence = [dbo].residence.idresidence LEFT OUTER JOIN [dbo].ateco WITH (NOLOCK) ON registry_aziende.idateco = [dbo].ateco.idateco LEFT OUTER JOIN [dbo].nace WITH (NOLOCK) ON registry_aziende.idnace = [dbo].nace.idnace LEFT OUTER JOIN [dbo].naturagiur WITH (NOLOCK) ON registry_aziende.idnaturagiur = [dbo].naturagiur.idnaturagiur LEFT OUTER JOIN [dbo].numerodip WITH (NOLOCK) ON registry_aziende.idnumerodip = [dbo].numerodip.idnumerodip WHERE  registry.idreg IS NOT NULL  AND registry_aziende.idreg IS NOT NULL 
GO

