-- CREAZIONE VISTA upbdefaultview
IF EXISTS(select * from sysobjects where id = object_id(N'[upbdefaultview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [upbdefaultview]
GO

CREATE VIEW [upbdefaultview] AS SELECT CASE WHEN upb.active = 'S' THEN 'Si' WHEN upb.active = 'N' THEN 'No' END AS upb_active,CASE WHEN upb.assured = 'S' THEN 'Si' WHEN upb.assured = 'N' THEN 'No' END AS upb_assured, upb.cigcode AS upb_cigcode, upb.codeupb AS upb_codeupb, upb.cofogmpcode AS upb_cofogmpcode, upb.ct AS upb_ct, upb.cu AS upb_cu, upb.cupcode AS upb_cupcode, upb.expiration AS upb_expiration, upb.flag AS upb_flag, upb.flagactivity AS upb_flagactivity, upb.flagkind AS upb_flagkind, upb.granted AS upb_granted, epupbkind.title AS epupbkind_title, epupbkind.description AS epupbkind_description, upb.idepupbkind AS upb_idepupbkind, treasurer.description AS treasurer_description, upb.idtreasurer, underwriter.description AS underwriter_description, upb.idunderwriter, upb.idupb, upbcapofila.title AS upbcapofila_title, upb.idupb_capofila, upb.lt AS upb_lt, upb.lu AS upb_lu, upb.newcodeupb AS upb_newcodeupb, upbparent.title AS upbparent_title, upb.paridupb, upb.previousappropriation AS upb_previousappropriation, upb.previousassessment AS upb_previousassessment, upb.printingorder AS upb_printingorder, upb.requested AS upb_requested, upb.ri_ra_quota AS upb_ri_ra_quota, upb.ri_rb_quota AS upb_ri_rb_quota, upb.ri_sa_quota AS upb_ri_sa_quota, upb.rtf AS upb_rtf, upb.start AS upb_start, upb.stop AS upb_stop, upb.title, upb.txt AS upb_txt, upb.uesiopecode AS upb_uesiopecode, isnull('Denominazione: ' + upb.title + '; ','') as dropdown_title FROM upb WITH (NOLOCK)  LEFT OUTER JOIN epupbkind WITH (NOLOCK) ON upb.idepupbkind = epupbkind.idepupbkind LEFT OUTER JOIN treasurer WITH (NOLOCK) ON upb.idtreasurer = treasurer.idtreasurer LEFT OUTER JOIN underwriter WITH (NOLOCK) ON upb.idunderwriter = underwriter.idunderwriter LEFT OUTER JOIN upb AS upbcapofila WITH (NOLOCK) ON upb.idupb_capofila = upbcapofila.idupb LEFT OUTER JOIN upb AS upbparent WITH (NOLOCK) ON upb.paridupb = upbparent.idupb WHERE  upb.idupb IS NOT NULL 
GO

